WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), launch_date) AS days_since_launch_date FROM products WHERE ARRAY_CONTAINS(tags, 'eco') OR ARRAY_CONTAINS(tags, 'premium')), agg AS (SELECT CASE WHEN stock_qty >= 407 THEN 'high' WHEN stock_qty >= 101 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, category, ROUND(STDDEV(days_since_launch_date), 2) AS stddev_days_since_launch_date FROM base GROUP BY CASE WHEN stock_qty >= 407 THEN 'high' WHEN stock_qty >= 101 THEN 'mid' ELSE 'low' END, category) SELECT stock_qty_bucket, category, stddev_days_since_launch_date FROM agg ORDER BY stock_qty_bucket, stddev_days_since_launch_date;
